public int visitFrameStart(int offset, final int numLocal, final int numStack) {
    // Handle potential invalid inputs
    if (offset < 0 || numLocal < 0 || numStack < 0) {
        throw new IllegalArgumentException("Invalid input arguments!");
    }

    // Handle potential runtime issues
    if (currentFrame == null) {
        throw new RuntimeException("Current frame is null!");
    }

    // Start the visit of a new stack map frame
    currentFrame.setOffset(offset);
    currentFrame.setNumLocal(numLocal);
    currentFrame.setNumStack(numStack);

    // Return the index of the next element to be written in this frame
    return currentFrame.nextElementIndex();
}

