            eolIndex++;
        }
        if (eolIndex < headerPart.length() && headerPart.charAt(eolIndex) == '\r'){
            eolIndex++;
            if (eolIndex < headerPart.length() && headerPart.charAt(eolIndex) == '\n'){
                eolIndex++;
            }
        }
        return eolIndex;
    }

private int parseEndOfLine(String headerPart, int end) {
    int index = end;
    while (index < headerPart.length() && headerPart.charAt(index) != '\r' && headerPart.charAt(index) != '\n') {
        index++;
    }
    if (index == headerPart.length()) {
        throw new IllegalArgumentException("Invalid header: no end of line found");
    }
    return index;
}

