public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Check if the input graph is null
    if (graph == null) {
        throw new IllegalArgumentException("Input graph must not be null");
    }

    // Create an empty graph with the same vertex and edge types as the input graph
    Graph<V, E> identityGraph = new Graph<>();

    // Add all the vertices from the input graph to the identity graph
    for (V vertex : graph.vertexSet()) {
        identityGraph.addVertex(vertex);
    }

    // Add all the edges from the input graph to the identity graph
    for (E edge : graph.edgeSet()) {
        identityGraph.addEdge(edge.getSrc().getId(), edge.getDest().getId(), edge);
    }

    // Create an isomorphism between the two graphs
    IsomorphicGraphMapping<V, E> isomorphism = new IsomorphicGraphMapping<>(graph, identityGraph);

    // Add the identity mapping to the isomorphism
    isomorphism.addMapping(graph.getId(), graph.getId());

    return isomorphism;
}

public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Check if the input graph is null
    Objects.requireNonNull(graph);

    // Create a trivial mapping that maps each vertex to itself
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<V, E>();
    for (V vertex : graph.vertices()) {
        mapping.put(vertex, vertex);
    }

    return mapping;
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Create an empty mapping
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>();

    // Iterate over the vertices of the graph
    for (V vertex : graph.vertices()) {
        // Add a mapping from the vertex to itself
        mapping.addMapping(vertex, vertex);
    }

    // Return the mapping
    return mapping;
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }

    return new IsomorphicGraphMapping<V,E>(graph, new ArrayList<V>(graph.getVertices()), new ArrayList<E>(graph.getEdges()));
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (file.isDirectory()) {
        deleteDirectory(file);
    } else {
        file.delete();
    }
}

private static void deleteDirectory(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }
    File[] files = directory.listFiles();
    if (files == null) {
        throw new IOException("Failed to list files in directory: " + directory);
    }
    for (File file : files) {
        deleteFile(file);
    }
    directory.delete();
}

private static void deleteFile(File file) throws IOException {
    if (!file.exists()) {
        return;
    }
    if (!file.delete()) {
        throw new IOException("Failed to delete file: " + file);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    // Validate input
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }

    // Schedule file for deletion on JVM exit
    file.deleteOnExit();

    // If file is directory, delete it and all sub-directories
    if (file.isDirectory()) {
        // Get all sub-directories
        File[] subDirectories = file.listFiles();

        // Delete each sub-directory and its contents
        for (File subDirectory : subDirectories) {
            forceDeleteOnExit(subDirectory);
        }
    }

    // Delete file
    file.delete();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    File[] files = file.listFiles();
    if (files != null && files.length > 0) {
        for (File f : files) {
            if (f.isDirectory()) {
                forceDeleteOnExit(f);
            } else {
                f.deleteOnExit();
            }
        }
    }
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        for (File child : files) {
            forceDeleteOnExit(child);
        }
    }
    file.deleteOnExit();
}

