public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Calculate the encoded size of the message
    int size = schema.getMessageSize(message);

    // Write the size of the message as a varint
    out.write(size);

    // Write the message to the stream
    CodedOutputStream codedOutput = CodedOutputStream.newInstance(out, buffer);
    schema.writeTo(codedOutput, message);
    codedOutput.flush();

    // Return the number of bytes written to the stream
    return size + 1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new NullPointerException("Argument must not be null");
    }

    // Get the size of the message
    int messageSize = getSize(message, schema, buffer);
    if (messageSize == 0) {
        throw new RuntimeException("Message size must not be 0");
    }

    // Write the message to the output stream
    out.write(messageSize);
    buffer.clear();
    schema.writeTo(message, buffer);
    buffer.write(out);

    return messageSize;
}

private static <T> int getSize(T message, Schema<T> schema, LinkedBuffer buffer) {
    int size = 0;
    try {
        buffer.clear();
        schema.writeTo(message, buffer);
        size = buffer.size();
    } catch (IOException e) {
        e.printStackTrace();
    }
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
  if (out == null) {
    throw new IllegalArgumentException("OutputStream cannot be null");
  }
  if (message == null) {
    throw new IllegalArgumentException("Message cannot be null");
  }
  if (schema == null) {
    throw new IllegalArgumentException("Schema cannot be null");
  }
  if (buffer == null) {
    buffer = LinkedBuffer.allocate();
  }

  ByteArrayBuffer byteBuffer = new ByteArrayBuffer();
  CodedOutputStream outputStream = CodedOutputStream.newInstance(byteBuffer);
  schema.writeTo(outputStream, message);
  int size = byteBuffer.size();

  outputStream.flush();
  outputStream.reset();

  outputStream.writeInt32NoTag(size);
  outputStream.writeRawBytes(byteBuffer.toByteArray());
  outputStream.flush();

  return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Invalid input: one or more null parameters");
    }

    int size = schema.getSerializedSize(message, buffer);
    ProtobufIOUtil.writeRawVarint32(out, size);
    ProtobufIOUtil.write(message, schema, out, buffer);

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    MessageAttachment attachment = new MessageAttachment(message, schema, buffer);
    int size = attachment.getSize();
    OutputStream outputStream = new OutputStream(size);
    attachment.write(outputStream);
    outputStream.flush();
    return size;
}

