public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] args = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            args[i] = getRawType(typeArguments[i]);
        }
        return args;
    } else {
        return null;
    }
}

private static Class<?> getRawType(Type type) {
    if (type instanceof Class) {
        return (Class<?>) type;
    } else if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        if (typeArguments.length > 0) {
            return getRawType(typeArguments[0]);
        } else {
            return null;
        }
    } else if (type instanceof TypeVariable) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        if (typeVariable.getBounds().length > 0) {
            return getRawType(typeVariable.getBounds()[0]);
        } else {
            return null;
        }
    } else {
        return null;
    }
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }

    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArgs = parameterizedType.getActualTypeArguments();
    Class<?>[] typeParameters = targetType.getTypeParameters();

    if (typeArgs.length != typeParameters.length) {
        return null;
    }

    Class<?>[] args = new Class<?>[typeArgs.length];

    for (int i = 0; i < typeArgs.length; i++) {
        Type typeArg = typeArgs[i];
        Class<?> typeParameter = typeParameters[i];

        if (typeArg instanceof Class) {
            args[i] = (Class<?>) typeArg;
        } else if (typeArg instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArg;
            args[i] = typeVariable.getGenericDeclaration().asSubclass(typeParameter);
        } else {
            return null;
        }
    }

    return args;
}

