public void accept(final METRICS data) {
    if (data == null) {
        throw new IllegalArgumentException("The data to be accepted cannot be null.");
    }
    if (this.cache == null) {
        this.cache = new HashSet<>(data.values());
    } else {
        this.cache.addAll(data.values());
    }
}

public void accept(final METRICS data) {
    // Validate input data
    if (Objects.isNull(data) || data.isEmpty()) {
        throw new IllegalArgumentException("Invalid data: null or empty.");
    }

    // Merge with existing value
    final METRICS existingValue = getValue();
    existingValue.merge(data);

    // Update the cache
    putValue(existingValue);
}

@Override
public void accept(final METRICS data) {
    if (data == null) {
        throw new IllegalArgumentException("Data cannot be null");
    }

    try {
        // Add the data to the cache
        cache.put(data.getKey(), data);

        // Merge the data with the existing value if it exists
        METRICS existingValue = cache.get(data.getKey());
        if (existingValue != null) {
            data.merge(existingValue);
        }
    } catch (Exception e) {
        throw new IllegalStateException("Error accepting data into the cache", e);
    }
}

public void accept(final METRICS data){
	if(data == null){
		throw new IllegalArgumentException("Missing data");
	}
	final String key = data.getKey();
	if(key == null){
		throw new IllegalArgumentException("Missing key");
	}
	synchronized(this){
		final MetricsValue existingValue = cache.get(key);
		if(existingValue == null){
			cache.put(key,new MetricsValue(data.getValue()));
		}else{
			existingValue.update(data.getValue());
		}
	}
}

