public void accept(final METRICS data) {
    if (data == null) {
        throw new IllegalArgumentException("Data cannot be null");
    }
    if (this.data.containsKey(data.getKey())) {
        this.data.get(data.getKey()).mergeWith(data);
    } else {
        this.data.put(data.getKey(), data);
    }
}

public void insertBefore(Bucket bucket) {
    if (bucket == null) {
      throw new IllegalArgumentException("The bucket cannot be null");
    }

    if (bucket.getNext() == null) {
      throw new RuntimeException("The bucket is already the last element in the list");
    }

    if (!bucket.getNext().equals(this)) {
      throw new IllegalStateException("The bucket is not in the list");
    }

    this.next = bucket;
    bucket.setNext(this);
  }

public void insertBefore(Bucket bucket) {
    // Check if the input bucket is null
    if (bucket == null) {
        throw new IllegalArgumentException("Input bucket cannot be null");
    }

    // Check if this bucket is already in the data structure
    if (this.list == null) {
        throw new UnsupportedOperationException("This bucket is not in the data structure");
    }

    // Check if the input bucket is already in the data structure
    if (bucket.list != null) {
        throw new UnsupportedOperationException("The input bucket is already in the data structure");
    }

    // Insert this bucket before the input bucket
    bucket.prev = this;
    bucket.next = this.next;

    // Update the links between the buckets
    this.next.prev = bucket;
    this.next = bucket;
}

void insertBefore(Bucket bucket){
        if(bucket != null){
            if(bucket.equals(this.next)){
                Bucket.setBucket(bucket.id, bucket.frequency, this.next);
            } else {
                Bucket updated = Bucket.setBucket(bucket.id, bucket.frequency, this.next);
                updated.next = this;
            }
        }
    }

public void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }

    if (this.store == null) {
        this.store = new ArrayList<>();
    }

    if (this.store.contains(bucket)) {
        int index = this.store.indexOf(bucket);
        Bucket temp = this.store.get(index);
        this.store.set(index, this);
        this.store.add(index + 1, temp);
    } else {
        throw new IllegalStateException("Bucket is not found in the data structure");
    }
}

void insertBefore(Bucket bucket) {
    // Check if the input bucket is not null
    if (bucket == null) {
        throw new IllegalArgumentException("The input bucket cannot be null");
    }

    // Check if the current bucket is already the first in the chain
    if (this.prev == null) {
        throw new IllegalStateException("The bucket is already the first in the chain");
    }

    // Link the current bucket with the input bucket
    this.prev.next = bucket;
    bucket.prev = this.prev;

    // Link the input bucket with the current bucket
    this.prev = bucket;
    bucket.next = this;
}

