public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || mappings == null) {
        return null;
    }
    Map<String, String> updatedMappings = new HashMap<>();
    for (Map.Entry<String, String> entry : mappings.entrySet()) {
        if (!entry.getKey().equals("_source")) {
            updatedMappings.put(entry.getKey(), entry.getValue());
        }
    }
    return new Mappings(tableName, updatedMappings);
}

def diffStructure(tableName: str, mappings: Mappings) -> Mappings:
    if not isinstance(tableName, str) or not isinstance(mappings, Mappings):
        raise ValueError("Invalid input type")

    current_index_mappings = get_mappings(tableName)
    input_mappings = mappings.copy()
    input_mappings.pop("_source", None)

    diff_mappings = dict()
    for field_name, field_type in current_index_mappings.items():
        if field_name not in input_mappings:
            diff_mappings[field_name] = field_type
    return diff_mappings

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Check if the input mappings are null or empty
    if (mappings == null || mappings.isEmpty()) {
        throw new IllegalArgumentException("Input mappings cannot be null or empty");
    }
    // Check if the table name is empty
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Table name cannot be null or empty");
    }
    // Get the current mappings for the table from the history mappings
    Mappings currentMappings = getCurrentMappings(tableName, mappings);
    // Create a new Mappings object to store the diff mappings
    Mappings diffMappings = new Mappings();
    // Iterate over the current mappings and compare with the input mappings
    for (Mapping currentMapping : currentMappings) {
        // Check if the input mappings contain the current mapping
        Mapping inputMapping = mappings.get(currentMapping.getName());
        if (inputMapping == null) {
            // If the input mappings do not contain the current mapping, add it to the diff mappings
            diffMappings.add(currentMapping);
        } else {
            // If the input mappings contain the current mapping, compare the field types
            if (!currentMapping.getType().equals(inputMapping.getType())) {
                // If the field types are different, add the current mapping to the diff mappings
                diffMappings.add(currentMapping);
            }
        }
    }
    // Remove the _source config from the diff mappings to avoid current index update conflict
    diffMappings.remove("_source");
    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Check if the input mappings are null or empty
    if (mappings == null || mappings.isEmpty()) {
        throw new IllegalArgumentException("Mappings cannot be null or empty");
    }

    // Create a new Mappings object to store the diff
    Mappings diffMappings = new Mappings();

    // Iterate over the input mappings and compare with the current mappings
    for (Map.Entry<String, Mapping> entry : mappings.entrySet()) {
        String fieldName = entry.getKey();
        Mapping fieldMapping = entry.getValue();

        // Check if the field exists in the current mappings
        if (!currentMappings.containsKey(fieldName)) {
            // If the field does not exist, add it to the diff mappings
            diffMappings.put(fieldName, fieldMapping);
        } else {
            // If the field exists, compare the mappings
            Mapping currentMapping = currentMappings.get(fieldName);
            if (!currentMapping.equals(fieldMapping)) {
                // If the mappings are different, add the field to the diff mappings
                diffMappings.put(fieldName, fieldMapping);
            }
        }
    }

    return diffMappings;
}

