    }
    return this.data[offset] | (this.data[offset + 1] << 8) | (this.data[offset + 2] << 16) | (this.data[offset + 3] << 24)
            | (this.data[offset + 4] << 32) | (this.data[offset + 5] << 40) | (this.data[offset + 6] << 48)
            | (this.data[offset + 7] << 56);
