protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long currentStart = start;
    long currentEnd = end;
    while (currentStart < currentEnd) {
        long duration = currentEnd - currentStart;
        if (duration > FETCH_DATA_DURATION) {
            throw new IllegalArgumentException("Start time must be smaller than end time");
        }
        try {
            timeRanges.add(new TimeRange(currentStart, duration));
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Start time must be smaller than end time", e);
        }
    }
    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    // Define the maximum duration for each time range
    long maxDuration = FETCH_DATA_DURATION;

    // Initialize an empty list to store the time ranges
    List<TimeRange> timeRanges = new ArrayList<>();

    // Loop through the start to end times and create time ranges
    for (long currentTime = start; currentTime < end; currentTime += maxDuration) {
        // Calculate the end time for the current time range
        long currentEndTime = Math.min(currentTime + maxDuration, end);

        // Create a new time range with the current start and end times
        TimeRange timeRange = new TimeRange(currentTime, currentEndTime);

        // Add the time range to the list
        timeRanges.add(timeRange);
    }

    return timeRanges;
}

def build_time_ranges(start, end):
    # Calculate the total duration
    total_duration = end - start

    # Check if the total duration is greater than the maximum allowed duration
    if total_duration > FETCH_DATA_DURATION:
        # Split the time range into multiple ranges
        num_splits = int(total_duration // FETCH_DATA_DURATION) + 1
        time_ranges = []
        for i in range(num_splits):
            time_ranges.append(TimeRange(start + i * FETCH_DATA_DURATION, start + (i + 1) * FETCH_DATA_DURATION))
        return time_ranges
    else:
        return [TimeRange(start, end)]

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Initialize an empty list to store the time ranges
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the duration of the current time range
    long duration = end - start;

    // If the duration is greater than the allowed fetch data duration, split the time range
    if (duration > FETCH_DATA_DURATION) {
        // Calculate the number of time ranges needed to cover the current time range
        int numTimeRanges = (int) Math.ceil((double) duration / FETCH_DATA_DURATION);

        // Calculate the start and end times for each time range
        for (int i = 0; i < numTimeRanges; i++) {
            long startTime = start + (i * FETCH_DATA_DURATION);
            long endTime = startTime + FETCH_DATA_DURATION;

            // Add the new time range to the list
            timeRanges.add(new TimeRange(startTime, endTime));
        }
    } else {
        // The duration is less than the allowed fetch data duration, so just add the current time range
        timeRanges.add(new TimeRange(start, end));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;

    if (start + duration > end) {
        timeRanges.add(TimeRange.fromStartEnd(start, start + duration - 1, null));
    } else {
        timeRanges.add(TimeRange.fromStartEnd(start, end, null));
    }

    return timeRanges;
}

