public static long compressTimeBucket(long timeBucket, int dayStep) {
  if (timeBucket < 0) {
    throw new IllegalArgumentException("timeBucket should be non-negative");
  }
  if (dayStep < 1) {
    throw new IllegalArgumentException("dayStep should be positive");
  }
  long daysInBucket = timeBucket / 1000000;
  long remainder = timeBucket % 1000000;
  long daysStepped = (daysInBucket / dayStep) * dayStep;
  long steppedTimeBucket = daysStepped * 1000000 + remainder;
  return steppedTimeBucket;
}

