  if (timeBucket < 0 || dayStep < 0) {
    throw new IllegalArgumentException("Invalid input: timeBucket and dayStep must be non-negative");
  }

  long modifiedTimeBucket = timeBucket - (timeBucket % dayStep);
  return modifiedTimeBucket;
}

