public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate input
    if (dayStep < 1 || dayStep > 31) {
        throw new IllegalArgumentException("Invalid dayStep: " + dayStep);
    }
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Invalid timeBucket: " + timeBucket);
    }

    // Calculate the number of days to shift the timeBucket
    int daysToShift = (dayStep - 1) * 10000;

    // Shift the timeBucket by the number of days
    long shiftedTimeBucket = timeBucket - daysToShift;

    // Calculate the new timeBucket value
    long newTimeBucket = shiftedTimeBucket - (shiftedTimeBucket % dayStep);

    return newTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Handle invalid input
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Time bucket must be a positive integer");
    }
    if (dayStep <= 0 || dayStep > 31) {
        throw new IllegalArgumentException("Day step must be a positive integer between 1 and 31");
    }

    // Calculate the number of days to add to the time bucket
    long numDays = dayStep - (timeBucket % dayStep);

    // Add the number of days to the time bucket
    timeBucket += numDays;

    // Return the re-formatted time bucket
    return timeBucket;
}

