    if (byteArrayValue == null) {
        throw new IllegalArgumentException("byteArrayValue cannot be null");
    }
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IllegalArgumentException("byteOffset must be a valid index in the byteArrayValue array");
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IllegalArgumentException("byteLength must be a valid number of bytes to copy from the byteArrayValue array");
    }
    if (byteLength == 0) {
        return this;
    }
    ensureCapacity(byteLength);
    System.arraycopy(byteArrayValue, byteOffset, this.data, this.writeIndex, byteLength);
    this.writeIndex += byteLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    Objects.requireNonNull(byteArrayValue);
    if (byteOffset < 0) {
        throw new IndexOutOfBoundsException("byteOffset < 0");
    }
    if (byteLength < 0) {
        throw new IndexOutOfBoundsException("byteLength < 0");
    }
    if (byteArrayValue.length - byteOffset < byteLength) {
        throw new IndexOutOfBoundsException("byteOffset + byteLength > byteArrayValue.length");
    }
    int newLength = Math.max(this.length, byteOffset + byteLength);
    if (this.bytes == null || this.bytes.length < newLength) {
        byte[] newBytes = new byte[newLength];
        if (this.bytes != null) {
            System.arraycopy(this.bytes, 0, newBytes, 0, this.bytes.length);
        }
        this.bytes = newBytes;
    }
    System.arraycopy(byteArrayValue, byteOffset, this.bytes, byteOffset, byteLength);
    this.length = Math.max(this.length, newLength);
    return this;
}

