public static String findAndSubst(String key, Properties props) {

    String value = props.getProperty(key);
    if (value == null) {
        throw new RuntimeException("No property found for key: " + key);
    }

    try {
        return substituteVariables(value, props);
    } catch (Exception e) {
        throw new RuntimeException("Error substituting variables in property value for key: " + key, e);
    }
}

