    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("Key not found: " + key);
    }
    return substituteVariables(value, props);
}

private static String substituteVariables(String value, Properties props) {
    Pattern regex = Pattern.compile("\\$\\{([^}]+)}");
    Matcher matcher = regex.matcher(value);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String variable = matcher.group(1);
        String replacement = props.getProperty(variable);
        if (replacement == null) {
            throw new IllegalArgumentException("Variable not found: " + variable);
        }
        matcher.appendReplacement(sb, replacement);
    }
    matcher.appendTail(sb);
    return sb.toString();
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("Key not found: " + key);
    }
    return substituteVars(value, props);
}

private static String substituteVars(String value, Properties props) {
    String result = value;
    int startIndex = 0;
    while (startIndex < result.length()) {
        int endIndex = result.indexOf("${", startIndex);
        if (endIndex == -1) {
            break;
        }
        int varStartIndex = endIndex + 2;
        int varEndIndex = result.indexOf("}", varStartIndex);
        if (varEndIndex == -1) {
            break;
        }
        String varName = result.substring(varStartIndex, varEndIndex);
        String varValue = props.getProperty(varName);
        if (varValue == null) {
            throw new IllegalArgumentException("Variable '" + varName + "' not found in properties");
        }
        result = result.substring(0, endIndex) + varValue + result.substring(varEndIndex + 1);
        startIndex = endIndex + 1;
    }
    return result;
}

public static String findAndSubst(String key,Properties props){
    if(key == null || props == null){
        throw new IllegalArgumentException("Key and props cannot be null");
    }
    String value = props.getProperty(key);
    if(value == null){
        throw new IllegalArgumentException("Value for key " + key + " not found");
    }
    return substitute(value, props, new Context());
}

