private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){

  // handle null inputs
  if(str == null || suffix == null){
    return str == null && suffix == null;
  }

  // check length of suffix
  if(suffix.length() > str.length()){
    return false;
  }

  // get the index at which the suffix starts
  int index = str.length() - suffix.length();

  // if ignoreCase is set to true, convert both strings to lowercase
  if(ignoreCase){
    str = str.toLowerCase();
    suffix = suffix.toLowerCase();
  }

  // check if the suffix matches at the given index
  boolean result = str.startsWith(suffix, index);

  return result;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String path = u.getPath();
    if (path == null) {
        throw new IllegalArgumentException("Path component cannot be null");
    }
    List<PathSegmentImpl> segments = new ArrayList<>();
    StringTokenizer st = new StringTokenizer(path, "/");
    while (st.hasMoreTokens()) {
        String token = st.nextToken();
        if (!token.isEmpty()) {
            segments.add(new PathSegmentImpl(token, decode));
        }
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegmentImplList = new ArrayList<>();
    String path = u.getPath();
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    for (String segment : path.split("/")) {
        pathSegmentImplList.add(new PathSegmentImpl(segment, decode));
    }
    return pathSegmentImplList;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] segments = path.split("/");
    for (String segment : segments) {
        if (decode) {
            segment = decodePathSegment(segment);
        }
        pathSegments.add(new PathSegmentImpl(segment));
    }
    return pathSegments;
}

private static String decodePathSegment(String segment) {
    try {
        return URLDecoder.decode(segment, "UTF-8");
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("Failed to decode path segment", e);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) throws URISyntaxException {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String path = u.getPath();
    if (path.isEmpty()) {
        return Collections.emptyList();
    }
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }
    String[] segments = path.split("/");
    List<PathSegmentImpl> decodedSegments = new ArrayList<>();
    for (String segment : segments) {
        decodedSegments.add(new PathSegmentImpl(segment, u.getScheme(), u.getHost(), decode));
    }
    return decodedSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
  // Initialize an empty list to store the path segments
  List<PathSegmentImpl> pathSegments = new ArrayList<>();

  // Get the path component of the URI
  String path = u.getPath();

  // Check if the path component is an absolute path component
  if (path.startsWith("/")) {
    // Ignore the leading '/' and treat it as not a delimiter of a path segment
    path = path.substring(1);
  }

  // Split the path component at each '/' character
  String[] segments = path.split("/");

  // Loop through each segment and decode it if necessary
  for (String segment : segments) {
    if (decode) {
      // Decode the segment using the decode() method
      segment = URLDecoder.decode(segment, "UTF-8");
    }
    // Add the decoded segment to the list of path segments
    pathSegments.add(new PathSegmentImpl(segment));
  }

  // Return the list of path segments
  return pathSegments;
}

