}

public Converter lookup(final Class<?> clazz) {
    // First, check if there is a direct match for the given class
    if (converters.containsKey(clazz)) {
        return converters.get(clazz);
    }

    // Next, check if there is a superclass match
    Class<?> superclass = clazz.getSuperclass();
    while (superclass != null) {
        if (converters.containsKey(superclass)) {
            return converters.get(superclass);
        }
        superclass = superclass.getSuperclass();
    }

    // Finally, check if there is an interface match
    for (Class<?> interfaceClass : clazz.getInterfaces()) {
        if (converters.containsKey(interfaceClass)) {
            return converters.get(interfaceClass);
        }
    }

    // No match found, return null
    return null;
}

public Converter lookup(final Class<?> clazz) {
    if (clazz == null) {
        throw new IllegalArgumentException("Class cannot be null");
    }
    for (Converter converter : converters) {
        if (converter.getTargetClass().equals(clazz)) {
            return converter;
        }
    }
    return null;
}

public Converter lookup(final Class<?> clazz) {
    Converter converter = converters.get(clazz);
    if (converter != null) {
        return converter;
    }
    for (Class<?> iface : clazz.getInterfaces()) {
        converter = converters.get(iface);
        if (converter != null) {
            return converter;
        }
    }
    return null;
}

public long readRawVarint64() throws IOException {
    // Read the raw Varint from the stream
    byte[] varint = new byte[10];
    int bytesRead = inputStream.read(varint);
    if (bytesRead < 10) {
        throw new IOException("Failed to read enough bytes for the Varint");
    }
    long value = 0;
    for (int i = 0; i < 10; i++) {
        value <<= 8;
        value |= varint[i];
    }
    return value;
}

public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (shift < 64) {
        final byte b = in.readByte();
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new MalformedVarintException("Varint too long");
}

public long readRawVarint64() throws IOException {
    long result = 0;
    int offset = 0;
    int b;
    do {
        b = in.read();
        if (b == -1) {
            if (offset == 0) {
                throw new IOException("Reached end of stream while trying to read Varint");
            } else {
                throw new IOException("Malformed Varint encoding, missing upper bits");
            }
        }
        result |= (long)(b & 0x7F) << offset;
        offset += 7;
    } while ((b & 0x80) != 0);
    return result;
}

public long readRawVarint64() throws IOException {
    long result = 0;
    int offset = 0;
    int b;
    do {
        b = readByte();
        result |= (b & 0x7F) << offset;
        offset += 7;
    } while ((b & 0x80) != 0);
    return result;
}

public long readRawVarint65 throws IOException {
  long result = 0;
  int offset = 0;

  while (offset < 64) {
    final byte b = readByte();
    result |= (long) (b & 0x7F) << offset;
    if ((b & 0x80) == 0) {
