private void pop(final String descriptor) throws RuntimeException {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    // Parse the descriptor to determine the number of types to pop
    int numTypes = 0;
    for (char c : descriptor.toCharArray()) {
        if (c == 'L' || c == '[') {
            numTypes++;
        }
    }

    // Pop the types from the output frame stack
    for (int i = 0; i < numTypes; i++) {
        if (!outputFrame.popType()) {
            throw new RuntimeException("Failed to pop type from output frame stack");
        }
    }
}

private void pop(final String descriptor) {
    int numAbstractTypesToPop = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        char currentChar = descriptor.charAt(i);
        if (currentChar == '(' || currentChar == 'L') {
            numAbstractTypesToPop++;
        } else if (currentChar == ')') {
            break;
        }
    }
    if (numAbstractTypesToPop > 0) {
        for (int i = 0; i < numAbstractTypesToPop; i++) {
            pop();
        }
    }
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Null descriptor");
    }

    // Note: This implementation only handles primitives and primitive wrappers, not object types or arrays.
    char type = descriptor.charAt(0);
    switch (type) {
        case 'B': // byte
        case 'Z': // boolean
        case 'C': // char
        case 'S': // short
        case 'I': // int
        case 'J': // long
        case 'F': // float
        case 'D': // double
            outputFrameStack.pop();
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

public void pop(final String descriptor) {
    int numAbstractTypes = 0;
    if (descriptor != null) {
        String[] descParts = descriptor.split(" ");
        String firstToken = descParts[0];
        if (firstToken.equals("(")) {
            numAbstractTypes++;
        } else if (firstToken.equals(")")) {
            numAbstractTypes -= 1;
        } else {
            numAbstractTypes = 0;
        }
    }
    while (numAbstractTypes > 0) {
        pop();
        numAbstractTypes--;
    }
}

private void pop(final String descriptor){
    // Check if descriptor is a type or method descriptor
    if (descriptor.contains("(")){
        // If it's a method descriptor, pop the argument types
        for (int i = 0; i < descriptor.length - 1; i++){
            if (descriptor.charAt(i) == 'L' && descriptor.charAt(i+1) == ';'){
                // Pop the type at the top of the stack
                stack.pop();
            }
        }
    } else {
        // If it's a type descriptor, pop the type
        stack.pop();
    }
}

