	if (arr.length == 0) {
		throw new IllegalArgumentException("The array is empty.");
	}
	if (i < 0 || i >= arr.length) {
		throw new IndexOutOfBoundsException("Index i is out of bounds.");
	}
	if (j < 0 || j >= arr.length) {
		throw new IndexOutOfBoundsException("Index j is out of bounds.");
	}
	if (i == j) {
		return;
	}

	V temp = arr[i];
	arr[i] = arr[j];
	arr[j] = temp;
}

