    long lastWriteTime = -1;
    try {
        // Get the current system time in milliseconds
        long currentTime = System.currentTimeMillis();
        // If the current time is greater than the last write time, update the last write time
        if (currentTime > lastWriteTime) {
            lastWriteTime = currentTime;
        }
        // Return the last write time in milliseconds
        return lastWriteTime;
    } catch (Exception e) {
        // Catch any exceptions and return the last write time, which will be -1 if no write has occurred
        return lastWriteTime;
    }
