    // Check if the source vertex is already present in the map
    if (!indexMap.containsKey(sourceVertex)) {
        // If not, create a new entry for the source vertex
        indexMap.put(sourceVertex, new HashMap<>());
    }

    // Check if the target vertex is already present in the map
    if (!indexMap.get(sourceVertex).containsKey(targetVertex)) {
        // If not, create a new entry for the target vertex
        indexMap.get(sourceVertex).put(targetVertex, new HashSet<>());
    }

    // Add the edge to the set of edges between the source and target vertices
    indexMap.get(sourceVertex).get(targetVertex).add(e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Source vertex, target vertex, and edge must not be null");
    }
    if (!containsVertex(sourceVertex) || !containsVertex(targetVertex)) {
        throw new IllegalArgumentException("Source and target vertices must be in the graph");
    }
    if (!containsEdge(e)) {
        throw new IllegalArgumentException("Edge must be in the graph");
    }
    EdgeIndex edgeIndex = getEdgeIndex(e);
    edgeIndex.put(sourceVertex, targetVertex);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Check if edge already exists
    if (this.containsEdge(sourceVertex, targetVertex, e)) {
        return;
    }

    // Add edge to adjacency list of source vertex
    if (!this.adjacencyList.containsKey(sourceVertex)) {
        this.adjacencyList.put(sourceVertex, new ArrayList<V>());
    }
    this.adjacencyList.get(sourceVertex).add(targetVertex);

    // Add edge to adjacency list of target vertex
    if (!this.adjacencyList.containsKey(targetVertex)) {
        this.adjacencyList.put(targetVertex, new ArrayList<V>());
    }
    this.adjacencyList.get(targetVertex).add(sourceVertex);

    // Add edge to edges list
    if (this.edges == null) {
        this.edges = new ArrayList<E>();
    }
    this.edges.add(e);
}

private static File[] classPath() {
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
    URL[] urls = ((URLClassLoader)classLoader).getURLs();
    File[] classPath = new File[urls.length];
    for (int i = 0; i < urls.length; i++) {
        try {
            classPath[i] = new File(urls[i].toURI());
        } catch (URISyntaxException e) {
            e.printStackTrace();
        }
    }
    return classPath;
}

