    String[] classPathElements = classPathProperty.split(separator);
    File[] classPath = new File[classPathElements.length];
    for (int i = 0; i < classPathElements.length; i++) {
        classPath[i] = new File(classPathElements[i]);
    }
    return classPath;
}

public static File[] classPath() {
    String classPathProperty = System.getProperty("java.class.path");
    if (classPathProperty == null || classPathProperty.isEmpty()) {
        throw new RuntimeException("Unable to retrieve class path from JVM");
    }
    String[] directories = classPathProperty.split(File.pathSeparator);
    List<File> classPaths = new ArrayList<>();
    for (String directory : directories) {
        File directoryFile = new File(directory);
        if (directoryFile.isDirectory()) {
            classPaths.add(directoryFile);
        }
    }
    return classPaths.toArray(new File[0]);
}

private static File[] classPath() throws URISyntaxException, IOException {
    String classPath = System.getProperty("java.class.path");
    String[] classPathElements = classPath.split(File.pathSeparator);
    File[] classPathFiles = new File[classPathElements.length];
    for (int i = 0; i < classPathElements.length; i++) {
        classPathFiles[i] = new File(new URI(classPathElements[i]));
    }
    return classPathFiles;
}

private static File[] classPath() {
    ClassLoader classLoader = ClassLoader.getSystemClassLoader();
    List<URL> urls = new ArrayList<>();
    while (classLoader != null) {
        URL[] classLoaderUrls = ((URLClassLoader) classLoader).getURLs();
        if (classLoaderUrls != null) {
            urls.addAll(Arrays.asList(classLoaderUrls));
        }
        classLoader = classLoader.getParent();
    }
    File[] classPathFiles = new File[urls.size()];
    for (int i = 0; i < urls.size(); i++) {
        classPathFiles[i] = new File(urls.get(i).getPath());
    }
    return classPathFiles;
}

