public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    double xMin = box.getMinX();
    double xMax = box.getMaxX();
    double yMin = box.getMinY();
    double yMax = box.getMaxY();

    if (xMin > xMax) {
        throw new IllegalArgumentException("Box must have a positive width");
    }

    double width = xMax - xMin;
    double splitX = xMin + (width / 2);

    Box2D box1 = new Box2D(xMin, yMin, splitX, yMax);
    Box2D box2 = new Box2D(splitX, yMin, xMax, yMax);

    return new Pair<>(box1, box2);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    // calculate the midpoint of the box
    Point2D midpoint = new Point2D.Double(box.getX() + (box.getWidth() / 2), box.getY());

    // calculate the width of the two resulting boxes
    double newWidth = box.getWidth() / 2;

    // create the two resulting boxes
    Box2D leftBox = new Box2D(box.getX(), box.getY(), newWidth, box.getHeight());
    Box2D rightBox = new Box2D(midpoint.getX(), box.getY(), newWidth, box.getHeight());

    return new Pair<Box2D,Box2D>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {

    // Calculate the midpoint of the box in the x dimension
    double midpoint = (box.x1 + box.x2) / 2;

    // Create two new boxes with the same y coordinates but different x coordinates
    Box2D box1 = new Box2D(box.y1, box.y2, midpoint, box.x2);
    Box2D box2 = new Box2D(box.y1, box.y2, box.x1, midpoint);

    // Return a pair of the two boxes
    return new Pair<Box2D,Box2D>(box1, box2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
	if (box == null) {
		throw new IllegalArgumentException("Box cannot be null");
	}

	Point2D min = box.getMin();
	Point2D max = box.getMax();

	double midX = (min.getX() + max.getX()) / 2;

	Box2D box1 = new Box2D(min, new Point2D(midX, max.getY()));
	Box2D box2 = new Box2D(new Point2D(midX, min.getY()), max);

	return new Pair<Box2D, Box2D>(box1, box2);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    if (box.getWidth() < 0) {
        throw new IllegalArgumentException("Width cannot be negative");
    }
    if (box.getHeight() < 0) {
        throw new IllegalArgumentException("Height cannot be negative");
    }
    double minX = box.getMinX();
    double maxX = box.getMaxX();
    double minY = box.getMinY();
    double maxY = box.getMaxY();
    double midX = (minX + maxX) / 2;
    double midY = (minY + maxY) / 2;
    Box2D box1 = new Box2D(minX, midX, minY, maxY);
    Box2D box2 = new Box2D(midX, maxX, minY, maxY);
    return new Pair<Box2D,Box2D>(box1, box2);
}

public void enlarge(int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    if (size == 0) {
        return;
    }
    int newSize = this.size + size;
    if (newSize < 0) {
        throw new IllegalArgumentException("New size must be non-negative");
    }
    T[] newData = (T[]) new Object[newSize];
    System.arraycopy(this.data, 0, newData, 0, this.size);
