}

public void enlarge(final int size) {
    if (size <= 0) {
        return;
    }

    int currentSize = this.size();
    int newSize = currentSize + size;

    if (newSize < 0) {
        throw new IllegalArgumentException("The size of the byte vector is too large, it cannot be enlarged more than " + (Integer.MAX_VALUE - currentSize) + " bytes.");
    }

    if (newSize > this.capacity()) {
        int doubleCapacity = this.capacity() * 2;
        if (doubleCapacity < 0) {
            doubleCapacity = Integer.MAX_VALUE;
        }
        int newCapacity = Math.max(newSize, doubleCapacity);
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(this.buffer, 0, newBuffer, 0, this.buffer.length);
        this.buffer = newBuffer;
        this.offset = 0;
        this.position = this.offset;
    }
}

private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    byte[] newBytes = new byte[size];
    if (m_buffer != null) {
        System.arraycopy(m_buffer, 0, newBytes, 0, m_length);
    }
    m_buffer = newBytes;
    m_length = size;
}

private void enlarge(final int size) {
    // Check if the vector needs to be enlarged
    if (size > 0) {
        // Create a new byte array with the additional size
        byte[] newData = new byte[data.length + size];
        // Copy the existing data to the new array
        System.arraycopy(data, 0, newData, 0, data.length);
        // Set the new data as the current data
        data = newData;
    }
}

private void enlarge(final int size) throws InvalidByteVectorException {
    // Validate input
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }

    // Calculate the new size
    int newSize = this.size + size;

    // Check if the vector needs to be enlarged
    if (newSize > this.capacity) {
        // Create a new array with the new size
        byte[] newArray = new byte[newSize];

        // Copy the contents of the current vector to the new array
        System.arraycopy(this.array, 0, newArray, 0, this.size);

        // Set the new array as the underlying array
        this.array = newArray;

        // Update the capacity
        this.capacity = newSize;
    }
}

