public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    // Validate inputs
    if (out == null || node == null) {
        throw new IllegalArgumentException("Invalid input: either the output or the node is null");
    }

    int totalContentSize = 0;

    // Write the node's content to the output stream
    totalContentSize = writeContent(out, node.getContent());

    // Write the node's children to the output stream
    for (LinkedBuffer child : node.getChildren()) {
        totalContentSize += writeTo(out, child);
    }

    return totalContentSize;
}

private static int writeContent(DataOutput out, byte[] content) throws IOException {
    if (content == null || content.length == 0) {
        return 0;
    }

    out.write(content);
    return content.length;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
if (node == null) {
throw new IllegalArgumentException("node must not be null");
}

int contentSize = 0;
while (node != null) {
contentSize += node.getBufferSize();
out.write(node.getBuffer(), 0, node.getBufferSize());
node = node.getNext();
}

return contentSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        out.write(current.buffer, 0, current.size);
        totalSize += current.size;
        current = current.next;
    }
    return totalSize;
}

