private void putAbstractTypes(final int start, final int end) {
    // Check if the start and end parameters are valid
    if (start < 0 || end < start || end > currentFrame.size()) {
        throw new IllegalArgumentException("Invalid start or end index");
    }

    // Iterate over the frame types in the current frame
    for (int i = start; i < end; i++) {
        // Get the current frame type
        FrameType frameType = currentFrame.get(i);

        // Write the abstract type of the frame type to the stack map table entries
        if (frameType.isAbstract()) {
            stackMapTableEntries.add(encodeVerificationTypeInfo(frameType.getAbstractType()));
        } else {
            stackMapTableEntries.add(encodeVerificationTypeInfo(frameType.getConcreteType()));
        }
    }
}

private String encodeVerificationTypeInfo(Type type) {
    // Implement type encoding based on the JVMS verification_type_info format
    // This is a simplified example, the actual implementation may be more complex
    if (type == Type.OBJECT) {
        return "L";
    } else if (type == Type.ARRAY) {
        return "[";
    } else {
        return type.toString();
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        Object type = currentFrame[i];
        if (type instanceof JavaObject) {
            putAbstractType((JavaObject) type);
        } else if (type instanceof JavaArray) {
            putAbstractType((JavaArray) type);
        } else if (type instanceof JavaClass) {
            putAbstractType((JavaClass) type);
        } else {
            throw new IllegalArgumentException("Unknown type: " + type.getClass().getName());
        }
    }
}

private void putAbstractType(JavaObject o) {
    ConstantPool cp = o.getConstantPool();
    int objectIndex = cp.addConstantUtf8(o.getClassName());
    putU1(CLASS_INDEX);
    putU2(objectIndex);
}

private void putAbstractType(JavaArray a) {
    ConstantPool cp = a.getConstantPool();
    int arrayIndex = cp.addConstantUtf8(a.getArrayName());
    putU1(ARRAY_INDEX);
    putU2(arrayIndex);
}

private void putAbstractType(JavaClass c) {
    ConstantPool cp = c.getConstantPool();
    int classIndex = cp.addConstantUtf8(c.getClassName());
    putU1(CLASS_INDEX);
    putU2(classIndex);
}

public void putAbstractTypes(final int start, final int end){
    // validate input
    if(start < 0 || end < 0 || start > end || end > currentFrame.length){
        throw new IllegalArgumentException("Invalid start or end index for currentFrame");
    }

    // iterate over types in the range start..end and put them in StackMapTable format
    for(int i = start; i < end; i++){
        AbstractType abstractType = currentFrame[i];
        if(abstractType instanceof ReferenceType){
            // if it's a reference type, put it in StackMapTable format
            stackMapTableEntries.add(new StackMapTableEntry.Class(((ReferenceType)abstractType).getInternalName(), false));
        }else if(abstractType instanceof BaseType){
            // if it's a base type, put it in StackMapTable format
            stackMapTableEntries.add(new StackMapTableEntry.BaseType(((BaseType)abstractType).getTypeCode()));
        }else{
            // if it's an invalid type, throw an exception
            throw new InvalidTypeException("The provided abstract type is not supported in StackMapTable");
        }
    }
}

private void putAbstractTypes(final int start, final int end){
    if(start < 0 || start > end || end >= currentFrame.size()){
        throw new IndexOutOfBoundsException("Invalid range: start=" + start + ", end=" + end + ", currentFrame.size()=" + currentFrame.size());
    }
    for(int i = start; i < end; i++){
        final Node node = currentFrame.get(i);
        if(node instanceof AbstractTypeNode){
            final AbstractTypeNode abstractTypeNode = (AbstractTypeNode)node;
            stackMapTableEntries.add(abstractTypeNode.getVerificationTypeInfo());
        }else{
            throw new IllegalStateException("Unexpected node type: " + node.getClass().getName());
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    // Handle potential invalid input parameters
    if (start < 0 || end < 0 || start >= currentFrame.length || end > currentFrame.length) {
        throw new IllegalArgumentException("Invalid start or end index");
    }

    // Iterate over the types in the current frame
    for (int i = start; i < end; i++) {
        VerificationTypeInfo typeInfo = (VerificationTypeInfo) currentFrame[i];
        if (typeInfo.getForm() != VerificationTypeInfo.FORM_OBJECT) {
            throw new IllegalStateException("Type at index " + i + " is not an abstract type");
        }

        // Write the type info to the stack map table entries
        stackMapTableEntries.add(typeInfo.getSourceInfo());
    }
}

