@Override
public String toString(JSONWriter.Feature... features) {

  // Handle invalid inputs by throwing an IllegalArgumentException
  if (features == null || features.length == 0) {
    throw new IllegalArgumentException(" features must not be null or empty ");
  }

  // Extract the valid features from the arguments
  List<JSONWriter.Feature> validFeatures = new ArrayList<>();
  for (JSONWriter.Feature feature : features) {
    if (feature != null && feature.isEnabled()) {
      validFeatures.add(feature);
    }
  }
  // Serialize to JSON String
  // If there are no valid features, return an empty string
  if (validFeatures.isEmpty()) {
    return "";
  }

  // Return a JSON string with the enabled features
  StringBuilder sb = new StringBuilder();
  for (JSONWriter.Feature feature : validFeatures) {
    // Use the feature's name as the key and coerce its value to a string
    sb.append(feature.getName()).append(": ").append(String.valueOf(feature.getValue()));
  }

  return sb.toString();
}

