    }
}

public String toString(JSONWriter.Feature... features) {
    if (features == null || features.length == 0) {
        return null;
    }

    JSONObject jsonObject = new JSONObject();
    for (JSONWriter.Feature feature : features) {
        switch (feature) {
            case INDENT_OUTPUT:
                jsonObject.put("indentOutput", true);
                break;
            case PRETTY_PRINT:
                jsonObject.put("prettyPrint", true);
                break;
            case SORT_PROPERTIES:
                jsonObject.put("sortProperties", true);
                break;
            case OMIT_NULL_VALUES:
                jsonObject.put("omitNullValues", true);
                break;
            case WRITE_NULLS:
                jsonObject.put("writeNulls", true);
                break;
            default:
                throw new IllegalArgumentException("Unknown feature: " + feature);
        }
    }

    return jsonObject.toJSONString();
}

