@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null || value == null) {
        throw new IllegalArgumentException("Type or value argument is null");
    }
    if (type.isAssignableFrom(Character.class)) {
        if (value instanceof Float) {
            return Character.toChars(((Float)value).intValue())[0];
        } else if (value instanceof Double) {
            return Character.toChars(((Double)value).intValue())[0];
        } else if (value instanceof Long) {
            return Character.toChars(((Long)value).intValue())[0];
        } else if (value instanceof Integer) {
            return Character.toChars(((Integer)value).intValue())[0];
        } else if (value instanceof Boolean) {
            return ((Boolean)value).booleanValue() ? Character.VALUE_TRUE : Character.VALUE_FALSE;
        } else if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            String strValue = (String)value;
            if (strValue.length() == 1) {
                return strValue.charAt(0);
            } else {
                throw new InvalidDataFormatException("String value cannot be converted to Character");
            }
        } else {
            throw new InvalidDataTypeException("Cannot convert type " + value.getClass().getName() + " to Character");
        }
    } else {
        throw new InvalidDataTypeException("Cannot convert to type " + type.getName());
    }
}

