public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 11) {
        return 11;
    }
    if (desiredCapacity < 1000) {
        return (int) Math.ceil(desiredCapacity / 10) * 10;
    }
    double prime = desiredCapacity;
    while (!isPrime(prime)) {
        prime += 1;
    }
    return (int) prime;
}

private static boolean isPrime(double number) {
    if (number == 2 || number == 3) {
        return true;
    }
    for (int i = 2; i <= Math.sqrt(number); i++) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity){
    if(desiredCapacity <= 0){
        throw new IllegalArgumentException("Desired capacity must be positive");
    }
    if(desiredCapacity == 1){
        return 1;
    }
    for(int i = (int)(desiredCapacity * 1.1) + 1; i < Integer.MAX_VALUE; i++){
        if(isPrime(i)){
            return i;
        }
    }
    return 0;
}

private static boolean isPrime(int num){
    if(num < 2){
        return false;
    }
    for(int i = 2; i * i <= num; i++){
        if(num % i == 0){
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }

    // Find the next prime number that is greater than or equal to the desired capacity
    boolean isPrime = false;
    int prime = 3;
    while (!isPrime) {
        isPrime = true;
        for (int i = 2; i <= Math.sqrt(prime); i++) {
            if (prime % i == 0) {
                isPrime = false;
                break;
            }
        }
        prime += 2;
    }

    // Return the calculated prime number
    return prime;
}

public static int nextPrime(int desiredCapacity) {
  if (desiredCapacity < 1) {
    throw new IllegalArgumentException("Desired capacity must be greater than 0");
  }

  int prime = 1;
  while (prime < desiredCapacity) {
    prime++;
    if (isPrime(prime)) {
      return prime;
    }
  }

  return prime;
}

private static boolean isPrime(int num) {
  if (num < 2) {
    return false;
  }

  for (int i = 2; i < num / 2; i++) {
    if (num % i == 0) {
      return false;
    }
  }

  return true;
}

public static int nextPrime(int desiredCapacity) {
    // Check for valid input
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be a positive integer");
    }

    // Find the next prime number that is close to the desired capacity
    int prime = desiredCapacity;
    while (!isPrime(prime)) {
        prime++;
    }

    // Return the prime number
    return prime;
}

public static boolean isPrime(int num) {
    // Check if the number is less than or equal to 1
    if (num <= 1) {
        return false;
    }

    // Check if the number is divisible by 2 to num-1
    for (int i = 2; i < num; i++) {
        if (num % i == 0) {
            return false;
        }
    }

    // If the number is not divisible by any number between 2 and num-1, it is prime
    return true;
}

