        throw new IOException("String length must be non-negative");
    }
    if (stream.remaining() < length) {
        throw new IOException("String too long for buffer");
    }
    byte[] data = new byte[length];
    stream.read(data);
    return new String(data, 0, length, StandardCharsets.UTF_8);
}

