public final byte[] toByteArray(){
        // Handle edge case where buffer is empty
        if (this.buffers.isEmpty()) {
            return new byte[0];
        }

        // Calculate total size of all buffers
        int totalSize = 0;
        for (ByteArrayBuffer buffer : this.buffers) {
            totalSize += buffer.size();
        }

        // Create a new byte[] of the total size and copy all buffer contents into it
        byte[] result = new byte[totalSize];
        int currentOffset = 0;
        for (ByteArrayBuffer buffer : this.buffers) {
            System.arraycopy(buffer.toByteArray(), 0, result, currentOffset, buffer.size());
            currentOffset += buffer.size();
        }

        return result;
    }

