public Object filter(Object msg) {
    if (msg instanceof BroadcastFilter) {
        BroadcastFilter filter = (BroadcastFilter) msg;
        if (filter.isEnabled()) {
            return filter.invoke();
        } else {
            return null;
        }
    } else {
        throw new IllegalArgumentException("Invalid message type. Expected BroadcastFilter, but got " + msg.getClass().getName());
    }
}

protected Object filter(Object msg) {
    if (msg == null) {
        throw new IllegalArgumentException("The message to filter cannot be null");
    }

    Object filteredMsg = null;
    try {
        // Invoke the  {@link BroadcastFilter}
        filteredMsg = msg;
    } catch (Exception e) {
        // Handle exception
        throw new RuntimeException("Error filtering message", e);
    }

    return filteredMsg;
}

@Override
protected Object filter(Object msg) {
    try {
        return this.filter.invoke(msg);
    } catch (Exception e) {
        LOG.error("Error while invoking broadcast filter", e);
        return null;
    }
}

protected Object filter(Object msg){
    // Check if the message is null
    if(msg == null){
        throw new NullPointerException("Message cannot be null");
    }

    // Check if the message is of the correct type
    if(!(msg instanceof Integer)){
        throw new ClassCastException("Message must be of type Integer");
    }

    // Invoke the BroadcastFilter
    int result = ((Integer)msg).intValue() + 1;

    return result;
}

protected Object filter(Object msg) {
    // Check if the message is valid
    if (msg == null || !(msg instanceof BroadcastMessage)) {
        throw new IllegalArgumentException("Invalid message type");
    }

    // Get the BroadcastFilter instance
    BroadcastFilter filter = getBroadcastFilter();

    // Invoke the filter
    try {
        return filter.filter((BroadcastMessage) msg);
    } catch (Exception e) {
        // Exception handling
        throw new RuntimeException("Failed to invoke the filter", e);
    }
}

