protected int removeUnusedNodes() {
    // 1. Initialize a counter for the number of nodes removed
    int numRemoved = 0;
    // 2. Traverse the tree starting from the root node
    for (Node node : tree) {
        // 3. Check if the current node is a leaf node
        if (node.isLeaf()) {
            // 4. If the node is a leaf node, check if it is inactive
            if (!node.isActive()) {
                // 5. If the node is inactive, remove it from the tree
                tree.remove(node);
                numRemoved++;
            }
        }
    }
    return numRemoved;
}

def removeUnusedNodes() {
  // The logic of this method is to traverse the Category tree
  // and mark each node as "unused" if it has no child nodes or leaves.

  // Base case: If the current node is a leaf or has no child nodes, mark it as unused.
  if (node.isLeaf() || !node.hasChildNodes()) {
    node.setUsed(false);
  }

  // Recursive case: If the current node has child nodes, recurse over them and mark the node as unused if all its child nodes are unused.
  else {
    for (Node child : node.getChildNodes()) {
      removeUnusedNodes(child);
    }

    if (node.getChildNodes().stream().allMatch(n - n.isUsed())) {
      node.setUsed(false);
    }
  }
}

public int removeUnusedNodes() {
    Category root = this.root;
    if (root == null) {
        return 0;
    }

    List<Category> nodesToRemove = new ArrayList<>();
    for (Category node : root.descendants()) {
        if (!node.isActive()) {
            nodesToRemove.add(node);
        }
    }

    for (Category node : nodesToRemove) {
        node.remove();
    }

    return nodesToRemove.size();
}

protected int removeUnusedNodes() {
        /*
         * Calculate the set of all categories that are not a parent of any other category
         */
        Set<Category> nonParents = Sets.difference(getAllCategories(), Sets.union(Sets.intersection(getAllUsedCategories(), getAllCategories()), Sets.newHashSet())).immutableCopy();
        /*
         * Calculate the set of all categories that have no products associated with them
         */
        Set<Category> unusedCategories = Sets.difference(getAllCategories(), getAllUsedCategories()).immutableCopy();

        /*
         * Remove the unused or inactive nodes from the tree
         */
        for (AbstractSetView<Category> categorySetView : Sets.powerSet(Sets.union(nonParents, unusedCategories))) {
            if (categorySetView.isEmpty()) {
                continue;
            }
            for (Category category : categorySetView) {
                if (!categorySetView.contains(category.getParent()) && category.getProducts().isEmpty()) {
                    removeCategory(category);
                }
            }
        }

        return getAllCategories().size();
    }

