public final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Validate the input
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPool.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }
    if (charBuffer == null || charBuffer.length == 0) {
        throw new IllegalArgumentException("Invalid char buffer");
    }

    // Read the string from the constant pool
    ConstantPoolEntry entry = constantPool[constantPoolEntryIndex];
    int length = entry.getPoolSize();
    String string = new String(entry.getData(), 0, length);

    // Copy the string into the char buffer
    for (int i = 0; i < length && i < charBuffer.length; i++) {
        charBuffer[i] = string.charAt(i);
    }

    return string;
}

final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer) {
    // Check if constant pool entry index is valid
    if (constantPoolEntryIndex < 0 || constantPoolPoolIndex >= classFileBuffer.length()) {
        throw new IndexOutOfBoundsException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // Check if char buffer is sufficient
    if (charBuffer.length < classFileBuffer.getShort(constantPoolEntryIndex + 2)) {
        throw new ArrayIndexOutOfBoundsException("Insufficient char buffer: " + charBuffer. length);
    }

    int length = classFileBuffer.getShort(constantPoolEntryIndex + 6);
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) classFileBuffer.getByte(constantPoolEntryIndex + 8 + i * 2);
    }
    return new String(charBuffer, 0, length);
}

