public final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Check if the constant pool entry index is valid
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("constantPoolEntryIndex is invalid");
    }

    // Check if the charBuffer is not null and has enough capacity
    if (charBuffer == null || charBuffer.length < getUtfLength(constantPoolEntryIndex)) {
        throw new NullPointerException("charBuffer is null or has insufficient capacity");
    }

    // Read the CONSTANT_Utf8 entry
    charBuffer[0] = (char)classFileBuffer[constantPoolEntryIndex];
    for (int i = 1; i < charBuffer.length; i++) {
        charBuffer[i] = (char)classFileBuffer[constantPoolEntryIndex + i];
    }

    return new String(charBuffer);
}

public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
  // Check if the constant pool entry index is valid
  if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPool.size()) {
    throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
  }

  // Check if the char buffer is large enough to hold the string
  if (charBuffer.length < constantPool.getConstant(constantPoolEntryIndex).getLength()) {
    throw new IllegalArgumentException("Char buffer too small to hold the string");
  }

  // Read the string from the constant pool entry and return it
  ConstantUtf8 constantUtf8 = (ConstantUtf8) constantPool.getConstant(constantPoolEntryIndex);
  constantUtf8.getString().getBytes(StandardCharsets.UTF_8, 0, constantUtf8.getLength(), charBuffer);
  return new String(charBuffer, 0, constantUtf8.getLength());
}

