private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circuit = new OuterFaceCirculator(start, dir);
    while (circuit.hasNext()) {
        Node currentNode = circuit.next();
        if (predicate.test(currentNode)) {
            return new OuterFaceCirculator(currentNode, dir);
        } else if (currentNode.equals(stop)) {
            return new OuterFaceCirculator(stop, dir);
        }
    }
    return new OuterFaceCirculator(start, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node must not be null");
    }
    if (dir != -1 && dir != 1) {
        throw new IllegalArgumentException("Direction must be either -1 or 1");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);
    while (circulator.hasNext()) {
        Node node = circulator.next();
        if (predicate.test(node)) {
            return circulator;
        }
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null || predicate == null) {
        throw new IllegalArgumentException("Start, stop, and predicate must not be null");
    }
    if (start == stop) {
        return OuterFaceCirculator.empty();
    }
    if (dir == 0) {
        dir = -1;
    }

    while (true) {
        Node curr = start;
        while (curr != stop) {
            Node next = curr.getNext();
            if (next == null) {
                return OuterFaceCirculator.empty();
            }
            if (predicate.test(curr)) {
                return OuterFaceCirculator.of(curr);
            }
            curr = next;
        }
        dir = -1 * dir;
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("predicate, start, and stop nodes must not be null");
    }
    if (start.equals(stop)) {
        throw new IllegalArgumentException("start and stop nodes must not be the same node");
    }
    if (dir != -1 && dir != 1) {
        throw new IllegalArgumentException("Invalid dir parameter: dir must be -1 or 1");
    }

    Node currentNode = start;
    Node nextNode = null;
    while (!currentNode.equals(stop)) {
        if (predicate.test(currentNode)) {
            return new OuterFaceCirculator(currentNode, dir);
        }
        nextNode = currentNode.get(dir);
        if (nextNode == null) {
            throw new IllegalStateException("The graph has an inner face, cannot be traversed on the outer face");
        }
        currentNode = nextNode;
    }

    return new OuterFaceCirculator(start, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);
    while (circulator.hasNext()) {
        Node node = circulator.next();
        if (predicate.test(node)) {
            return circulator.prev();
        }
    }
    return circulator.prev();
}

