public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        throw new NullPointerException("byteArrayValue must not be null");
    }
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset must be non-negative and less than the length of byteArrayValue");
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("byteLength must be non-negative and less than or equal to the length of byteArrayValue - byteOffset");
    }

    int newSize = length + byteLength;
    ensureCapacity(newSize);

    System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);

    length = newSize;

    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        if (byteLength < 0) {
            throw new IllegalArgumentException("byteLength cannot be negative");
        }
        ensureCapacity(byteLength);
        for (int i = 0; i < byteLength; i++) {
            data[count++] = (byte) 0;
        }
        return this;
    }

    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset out of range");
    }

    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("byteLength out of range");
    }

    ensureCapacity(byteLength);
    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        data[count++] = byteArrayValue[i];
    }
    return this;
}

