    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new ArrayIndexOutOfBoundsException("byteLength cannot be negative or greater than byteArrayValue.length - byteOffset");
    }
    ensureCapacity(byteLength);
