  if (charsToDelete == null || charsToDelete.isEmpty()) {
    return inString;
  }

  // Create a new StringBuffer to build the resulting String
  StringBuffer sb = new StringBuffer();

  // Iterate through the inString and append each character to the StringBuffer
  // unless it is in the charsToDelete String
  for (int i = 0; i < inString.length(); i++) {
    char c = inString.charAt(i);
    if (!charsToDelete.contains(String.valueOf(c))) {
      sb.append(c);
    }
  }

  // Return the resulting String
  return sb.toString();
}

