public final MatchResult match(CharSequence uri){
        // Handle invalid inputs
        if (uri == null || uri.length() == 0) {
            throw new IllegalArgumentException("Invalid URI: " + uri);
        }

        // Handle runtime issues
        try {
            // Apply the pattern to the URI
            Pattern pattern = Pattern.compile(this.pattern);
            Matcher matcher = pattern.matcher(uri);

            // Check for a match
            if (matcher.matches()) {
                // Extract the matched groups
                Map<String, String> groups = new HashMap<>();
                for (int i = 1; i <= matcher.groupCount(); i++) {
                    groups.put(matcher.group(i), matcher.group(i));
                }

                // Return the match result
                return new MatchResult(pattern, groups);
            } else {
                return null;
            }
        } catch (PatternSyntaxException e) {
            throw new IllegalArgumentException("Invalid pattern: " + this.pattern, e);
        }
    }

@Override
public MatchResult match(CharSequence uri) {
    try {
        Pattern pattern = Pattern.compile(this.pattern);
        Matcher matcher = pattern.matcher(uri);
        if (matcher.matches()) {
            return new MatchResult(matcher);
        } else {
            return null;
        }
    } catch (PatternSyntaxException e) {
        throw new UnableToMatchException("Unable to match the given URI against the pattern.", e);
    }
}

public final MatchResult match(CharSequence uri) {
    if (uri == null) {
        throw new IllegalArgumentException("Invalid input: uri is null");
    }
    if (uri.length() == 0) {
        throw new IllegalArgumentException("Invalid input: uri is empty");
    }
    if (!isValidUri(uri)) {
        throw new IllegalArgumentException("Invalid input: uri does not conform to the URI syntax");
    }

    MatchResult matchResult = new MatchResult();
    Matcher matcher = pattern.matcher(uri);
    if (matcher.find()) {
        matchResult.setMatched(true);
        matchResult.setMatcher(matcher);
    }
    return matchResult;
}

public static byte convertHexDigit(byte b) {
    if (b < 0 || b > 16) {
        throw new IllegalArgumentException("Invalid hex digit: " + b);
    }
    if (b >= 0 && b <= 9) {
        return b - '0';
    } else if (b >= 10 && b <= 15) {
        return b - 'a' + 10;
    } else {
        throw new IllegalArgumentException("Invalid hex digit: " + b);
    }
}

