private void refillBuffer() throws IOException {
   if (inputStream.available() == 0) {
       throw new EOFException("No more data available in the input stream");
   }

   buffer.clear();
   int bytesRead = inputStream.read(buffer);
   buffer.flip();

   if (bytesRead == 0) {
       throw new IOException("Failed to read data from the input stream");
   }
}

