public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour == null || tour.isEmpty()){
        throw new IllegalArgumentException("Tour must not be null or empty");
    }
    if(graph == null || graph.getEdgeSet().isEmpty()){
        throw new IllegalArgumentException("Graph must not be null or empty");
    }

    // Create a new graph path
    GraphPath<V,E> path = new GraphPath<V,E>();

    // Add the first vertex to the path
    V startVertex = tour.iterator().next().getOpposite(graph.getFirstVertex());
    path.addVertex(startVertex);

    // Loop through the edges in the tour
    for(E edge : tour){
        V currentVertex = edge.getOpposite(startVertex);
        path.addVertex(currentVertex);
        path.addEdge(edge);
        startVertex = currentVertex;
    }

    // Add the last vertex to the path
    V endVertex = tour.iterator().next().getOpposite(null);
    path.addVertex(endVertex);

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if(tour == null || graph == null){
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if(tour.isEmpty()){
        throw new IllegalArgumentException("Tour must not be empty");
    }
    if(!tour.containsAll(graph.getEdges())){
        throw new IllegalArgumentException("Tour must contain all edges of the graph");
    }
    return new GraphPath<V,E>(tour.toArray(new E[tour.size()]),graph);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    try{
        // check if tour is empty
        if(tour.isEmpty()){
            throw new IllegalArgumentException("Tour cannot be empty");
        }
        // create a new graph path
        GraphPath<V,E> path = new GraphPath<V,E>();
        // iterate over the edges in the tour
        for(E edge : tour){
            // add the edge to the path
            path.addEdge(edge);
        }
        // return the graph path
        return path;
    }catch(Exception e){
        // handle exception
        System.out.println("Error: " + e.getMessage());
        return null;
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour must not be null or empty.");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null.");
    }
    List<E> edges = new LinkedList<>(tour);
    List<E> path = new LinkedList<>();
    for (E edge : edges) {
        if (graph.containsEdge(edge)) {
            path.add(edge);
        }
    }
    return new GraphPathImpl<>(graph, path);
}

