public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        Constant_Info info = constantPool.get(i);
        if (info instanceof Constant_NameAndType_Info) {
            Constant_NameAndType_Info nameAndTypeInfo = (Constant_NameAndType_Info) info;
            if (nameAndTypeInfo.name.equals(name) && nameAndTypeInfo.descriptor.equals(descriptor)) {
                // If found, return the already existing Symbol
                return nameAndTypeInfo.getSymbol();
            }
        }
    }

    // If not found, create a new Symbol and add it to the constant pool
    Constant_NameAndType_Info newNameAndTypeInfo = new Constant_NameAndType_Info(name, descriptor);
    constantPool.add(newNameAndTypeInfo);
    return newNameAndTypeInfo.getSymbol();
}

public Symbol addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || name.isEmpty() || descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Name and descriptor must not be null or empty");
    }

    // Check if the constant pool already contains an item with the same name and descriptor
    for (Symbol symbol : constantPool) {
        if (symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            return symbol;
        }
    }

    // If not, create a new Symbol and add it to the constant pool
    Symbol newSymbol = new Symbol(name, descriptor);
    constantPool.add(newSymbol);
    return newSymbol;
}

public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if a similar item already exists in the constant pool
    if (constantPool.contains(new Symbol(name, descriptor))) {
        return constantPool.get(name, descriptor);
    }

    // Create a new Symbol for the given name and descriptor
    Symbol symbol = new Symbol(name, descriptor);

    // Add the symbol to the constant pool
    constantPool.add(symbol);

    return symbol.index;
}

public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constant_pool_size; i++) {
        if (constant_pool[i].tag == ConstantPoolTags.CONSTANT_NameAndType &&
                constant_pool[i].name.equals(name) &&
                constant_pool[i].descriptor.equals(descriptor)) {
            // If a similar item is found, return it
            return i;
        }
    }

    // If no similar item is found, add a new one to the constant pool
    int index = constant_pool_size++;
    ConstantPoolNameAndType constant = new ConstantPoolNameAndType();
    constant.tag = ConstantPoolTags.CONSTANT_NameAndType;
    constant.name = name;
    constant.descriptor = descriptor;
    constant_pool[index] = constant;

    // Return the index of the new item
    return index;
}

