    constants.put(name, descriptor, new Symbol(name, descriptor));
    return new Symbol(name, descriptor);
}

private String unescapeId(String input) {
    if (input == null || input.isEmpty()) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i < input.length() - 1) {
                char nextChar = input.charAt(i + 1);
                if (nextChar == '\\') {
                    output.append(c);
                    i++;
                } else if (nextChar == 'u') {
                    if (i < input.length() - 4) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            int codePoint = Integer.parseInt(hex, 16);
                            output.append(Character.toChars(codePoint));
                            i += 5;
                        } catch (NumberFormatException e) {
                            throw new IllegalArgumentException("Invalid Unicode escape sequence: " + hex);
                        }
                    } else {
                        throw new IllegalArgumentException("Incomplete Unicode escape sequence");
                    }
                } else {
                    output.append(c);
                }
            } else {
                throw new IllegalArgumentException("Incomplete escape sequence");
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

private String unescapeId(String input) {
    // Replace any escaped double quotes with a single quote
    String result = input.replaceAll("\\\\\"", "'");

    // Replace any escaped backslashes with a single backslash
    result = result.replaceAll("\\\\\\\\", "\\\\");

    // Remove any surrounding double quotes
    result = result.replaceAll("^\"|\"$", "");

    return result;
}

private String unescapeId(String input){
     // validate input
     if(input == null){
         throw new IllegalArgumentException("input cannot be null");
     }
     // check if input contains escape characters
     if(input.contains("\\")){
         // escape the escape characters
         input = input.replace("\\", "\\\\");
     }
     // check if input contains "\"
     if(input.contains("\"")){
         // escape the special character
         input = input.replace("\"", "\\\"");
     }
     // check if input contains newline characters
     if(input.contains("\n")){
         // escape the newline character
         input = input.replace("\n", "\\n");
     }
     // check if input contains return characters
     if(input.contains("\r")){
         // escape the return character
         input = input.replace("\r", "\\r");
     }
     // check if input contains tab characters
     if(input.contains("\t")){
         // escape the tab character
         input = input.replace("\t", "\\t");
     }
     return input;
 }

public String unescapeId(String input){
    // Validate input string
    if(input == null){
        throw new IllegalArgumentException("Input string is null");
    }

    // Handle empty input string
    if(input.isEmpty()){
        return "";
    }

    // Replace escape sequences with corresponding characters
    String unescapedInput = input.replace("\\\\", "\\");
    unescapedInput = unescapedInput.replaceAll("\\\\n", "\n");
    unescapedInput = unescapedInput.replaceAll("\\\\t", "\t");
    unescapedInput = unescapedInput.replaceAll("\\\\", "/");

    return unescapedInput;
}

