private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Check if the minimum label is valid
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid minimum label: " + minLabel);
    }

    // Get the set of vertices with the minimum label
    Set<Integer> minLabelVertices = bucketsByLabel.get(minLabel);

    // Move all vertices from the set to the bucket with label 0
    for (Integer vertex : minLabelVertices) {
        labels.set(vertex, 0);
        bucketsByLabel.get(0).add(vertex);
    }

    // Clear the bucket with the minimum label
    bucketsByLabel.set(minLabel, new HashSet<>());

    // Update the labeling accordingly
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            labels.set(i, 0);
        }
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from the bucket with label 'minLabel' to the bucket with label 0
    Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
    Set<Integer> targetBucket = bucketsByLabel.get(0);
    for (Integer vertex : sourceBucket) {
        targetBucket.add(vertex);
    }
    // Clear the bucket with label 'minLabel'
    sourceBucket.clear();

    // Update the labeling accordingly
    for (Integer vertex : targetBucket) {
        int vertexLabel = labels.get(vertex);
        if (vertexLabel == minLabel) {
            labels.set(vertex, 0);
        }
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input");
    }

    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    if (minLabelBucket.isEmpty()) {
        return;
    }

    int newLabel = minLabel == 0 ? 0 : minLabel - 1;

    for (Integer vertex : minLabelBucket) {
        labels.set(vertex, newLabel);
    }

    bucketsByLabel.get(newLabel).addAll(minLabelBucket);
    minLabelBucket.clear();
}

public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Step 1: Move all vertices from the bucket with label minLabel to the bucket with label 0
    Set<Integer> bucketWithMinLabel = bucketsByLabel.get(minLabel);
    Set<Integer> bucket0 = bucketsByLabel.get(0);
    for (Integer vertex : bucketWithMinLabel) {
        bucket0.add(vertex);
        labels.set(vertex, 0);
    }
    bucketWithMinLabel.clear();

    // Step 2: Update the labeling accordingly
    for (int label = minLabel + 1; label < bucketsByLabel.size(); label++) {
        Set<Integer> bucket = bucketsByLabel.get(label);
        for (Integer vertex : bucket) {
            labels.set(vertex, label - 1);
        }
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // check input is valid
    if (bucketsByLabel == null || labels == null || minLabel < 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    // check minLabel is valid
    if (minLabel >= bucketsByLabel.size()) {
        throw new IndexOutOfBoundsException("Invalid minLabel");
    }

    // move all vertices in minLabel bucket to bucket 0
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    if (minLabelBucket != null) {
        bucketsByLabel.set(0, minLabelBucket);
        minLabelBucket.clear();
    }

    // update labels of vertices in bucket 0
    Set<Integer> bucket0 = bucketsByLabel.get(0);
    if (bucket0 != null) {
        for (Integer vertex : bucket0) {
            labels.set(vertex, 0);
        }
    }
}

