public static int countOccurrencesOf(String str, String sub) {
    if (str == null || sub == null) {
        return 0;
    }
    int count = 0;
    int index = str.indexOf(sub);
    while (index != -1) {
        count++;
        index = str.indexOf(sub, index + 1);
    }
    return count;
}

public static int countOccurrencesOf(String str, String sub) {
    // check if either input string is null or empty
    if (str == null || str.isEmpty() || sub == null || sub.isEmpty()) {
        return 0;
    }

    // initialize variables
    int count = 0;
    int index = 0;

    // loop through the input string and search for the substring
    while (index < str.length()) {
        // check if the current character matches the first character of the substring
        if (str.charAt(index) == sub.charAt(0)) {
            // check if the substring matches the current character
            if (str.startsWith(sub, index)) {
                count++;
                // update the substring's starting index to the index after the current substring
                index += sub.length();
            } else {
                // increment the index by one to check the next character
                index++;
            }
        } else {
            // increment the index by one to check the next character
            index++;
        }
    }

    return count;
}

