    }
    buffer.append(";");
} catch (Exception e) {
    e.printStackTrace();
}

protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {

  // Check if the array is null
  if (array == null) {
    buffer.append(fieldName).append("=null");
    return;
  }

  // Initialize the string for the byte array
  boolean isFirst = true;
  String byteArrayStr = "{";

  // Loop through the byte array and append each byte
  for (int i = 0; i < array.length; i++) {
    if (isFirst) {
      isFirst = false;
    } else {
      byteArrayStr += ", ";
    }
    byteArrayStr += array[i];
  }

  // Add the closing brace for the byte array and append it to the buffer
  byteArrayStr += "}";
  buffer.append(fieldName).append("=bool>").append(byteArrayStr);
}

