private void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("The number of elements to pop must be non-negative");
    }

    if (elements > m_outputStack.size()) {
        throw new IllegalArgumentException("The number of elements to pop must not exceed the size of the output stack");
    }

    while (elements > 0) {
        m_outputStack.pop();
        elements--;
    }
}

public void pop(int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("elements cannot be negative");
    }
    if (elements > outputStack.size()) {
        throw new IllegalArgumentException("elements cannot be greater than the size of the output stack");
    }
    for (int i = 0; i < elements; i++) {
        outputStack.pop();
    }
}

public void pop(int elements) throws IndexOutOfBoundsException {
    if (elements < 0) {
      throw new IndexOutOfBoundsException("The number of elements to pop cannot be negative");
    }
    if (elements > outputFrameStack.size()) {
      throw new IndexOutOfBoundsException("The number of elements to pop cannot be greater than the size of the output frame stack");
    }
    for (int i = 0; i < elements; i++) {
      outputFrameStack.pop();
    }
  }

private void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("Cannot pop a negative number of elements");
    }
    if (elements > currentFrame.getSize()) {
        throw new IllegalArgumentException("Cannot pop more elements than are currently on the stack");
    }
    int index = currentFrame.getSize() - elements;
    for (int i = 0; i < elements; i++) {
        AbstractType type = currentFrame.get(index + i);
        currentFrame.remove(index + i);
        interpreter.executeAndPop(type);
    }
}

public void pop(int elements) {
	// Check if elements is valid
	if (elements < 0) {
		throw new IllegalArgumentException("Number of elements to pop must be non-negative");
	}

	// Get the current output frame and its stack
	Frame currentFrame = getCurrentFrame();
	if (currentFrame == null) {
		throw new RuntimeException("No frame is currently being output");
	}
	Stack<AbstractType> stack = currentFrame.getStack();

	// Pop the specified number of abstract types from the stack
	for (int i = 0; i < elements; i++) {
		if (stack.isEmpty()) {
			throw new RuntimeException("Cannot pop from empty stack");
		}
		stack.pop();
	}
}

