    // Check if the bucket is the same
    if (this.bucket.hashCode() == dataset.bucket.hashCode()) {
        return true;
    } else {
        // If the bucket is not the same, check if the dataset is empty
        if (dataset.isEmpty()) {
            // If the dataset is empty, return false
            return false;
        } else {
            // If the dataset is not empty, check if the top element is a variable
            DataItem topItem = dataset.peekItem();
            if (topItem.getType() == DataType.VARIABLE) {
                // If the top element is a variable, check if it is the same as the current bucket
                String variableName = topItem.getValue().toString();
                if (variableName.equals(this.bucket.getVariableName())) {
                    return true;
                }
            }
        }
    }
    return false;
}

