public void overrideName(String oldName, String newName) {
    if (oldName == null || newName == null) {
        throw new IllegalArgumentException("Both old and new names must be non-null");
    }
    if (oldName.equals(newName)) {
        return;
    }
    if (newName.isEmpty()) {
        throw new IllegalArgumentException("New name must not be empty");
    }

    if (storageLevel.isLevelHigher(oldName, newName)) {
        String parentName = storageLevel.getParentName(oldName);
        // If there is a parent name, recursively check if it's being replaced
        if (parentName != null) {
            overrideName(parentName, newName);
        }
    }
    storageLevel.renameKey(oldName, newName);
}

def overrideName(oldName, newName):
    """
    Keep the same name replacement as  {@link ColumnName#overrideName(String,String)}
    @param oldName to be replaced.
    @param newName to use in the storage level.
    """
    # Check if the oldName is valid
    if oldName is None or oldName == "":
        raise ValueError("oldName cannot be None or empty")
    # Check if the newName is valid
    if newName is None or newName == "":
        raise ValueError("newName cannot be None or empty")
    # Check if the oldName exists in the storage level
    if not oldName in self.storageLevel:
        raise ValueError(f"oldName '{oldName}' does not exist in the storage level")
    # Replace the oldName with the newName in the storage level
    self.storageLevel.replace(oldName, newName)

public void overrideName(String oldName,String newName){
  if(oldName is null){
    throw new IllegalArgumentException("oldName cannot be null");
  }

  if(newName is null){
    throw new IllegalArgumentException("newName cannot be null");
  }

  if(oldName.isEmpty()){
    throw new IllegalArgumentException("oldName cannot be empty");
  }

  if(newName.isEmpty()){
    throw new IllegalArgumentException("newName cannot be empty");
  }

  if(oldName.equals(newName)){
    return;
  }

  boolean renamed = false;
  for(int i = 0; i < this.columnNames.size(); i++){
    if(this.columnNames.get(i).equals(oldName)){
      this.columnNames.set(i, newName);
      renamed = true;
      break;
    }
  }

  if(!renamed){
    throw new IllegalArgumentException(oldName + " not found in column names");
  }
}

public void overrideName(String oldName, String newName) {
