    throw new IllegalArgumentException("Node is not in the list");
  }

  ListNodeImpl<E> previous = node.previous;
  ListNodeImpl<E> next = node.next;
  previous.next = next;
  next.previous = previous;
  node.previous = null;
  node.next = null;

  return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null || node.prev == null || node.next == null) {
        throw new IllegalArgumentException("Node must not be null and must have both previous and next nodes");
    }

    node.prev.next = node.next;
    node.next.prev = node.prev;
    node.prev = null;
    node.next = null;
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new NullPointerException("Node cannot be null");
    }
    if (node.getNext() == null) {
        throw new IllegalArgumentException("Node is not in the list");
    }
    if (node.getNext() == node.getPrev()) {
        throw new IllegalArgumentException("Node is the only node in the list");
    }

    ListNodeImpl<E> prev = node.getPrev();
    ListNodeImpl<E> next = node.getNext();
    prev.setNext(next);
    next.setPrev(prev);
    node.setNext(null);
    node.setPrev(null);

    return true;
}

