public static final <V>void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("The array cannot be null");
    }
    if (from < 0 || to < 0 || from > to || to >= arr.length) {
        throw new IllegalArgumentException("Invalid range");
    }
    int mid = (from + to) / 2;
    for (int i = from; i <= mid; i++) {
        int mirrorIndex = to - (i - from);
        V temp = arr[i];
        arr[i] = arr[mirrorIndex];
        arr[mirrorIndex] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    if (from < 0 || from >= arr.length) {
        throw new IndexOutOfBoundsException("From index out of bounds");
    }

    if (to < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("To index out of bounds");
    }

    if (from > to) {
        throw new IllegalArgumentException("From index must be less than or equal to to index");
    }

    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0 || from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
        throw new IllegalArgumentException("Invalid input parameters");
    }
    if (from == to) {
        return;
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

public static final <V>void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0 || from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
        throw new IllegalArgumentException("Invalid input");
    }

    int left = from;
    int right = to;

    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("The array cannot be null or empty");
    }
    if (from < 0 || from >= arr.length) {
        throw new IndexOutOfBoundsException("The 'from' index is out of bounds");
    }
    if (to < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("The 'to' index is out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("The 'from' index must be less than or equal to the 'to' index");
    }

    int i = from, j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

