public void putAllWriteable(BeanMap map) {
    try {
        for (String propertyName : map.keySet()) {
            boolean readOnly = map.getDescriptor(propertyName).isReadOnly();
            boolean writeOnly = map.getDescriptor(propertyName).isWriteOnly();
            if (readOnly || writeOnly) {
                continue;
            }
            Object value = map.get(propertyName);
            this.put(propertyName, value);
        }
    } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException("Invalid property name: " + e.getMessage(), e);
    } catch (IllegalAccessException e) {
        throw new IllegalAccessException("Unable to access property: " + e.getMessage(), e);
    } catch (InvocationTargetException e) {
        throw new RuntimeException("Error occurred while putting values into the BeanMap", e);
    }
}

