public ByteVector putInt(final int intValue) {
    if (intValue > MAX_INT || intValue < MIN_INT) {
        throw new IllegalArgumentException("Int value out of range: " + intValue);
    }
    if (intValue < 0) {
        intValue = (~intValue) + 1;
    }
    putShort((short) intValue);
    putShort((short) (intValue >>> 16));
    return this;
}

public ByteVector putInt(final int intValue) {
    ensureCapacity(4);
    putByte((byte) (intValue & 0xFF));
    putByte((byte) ((intValue >> 8) & 0xFF));
    putByte((byte) ((intValue >> 16) & 0xFF));
    putByte((byte) ((intValue >> 24) & 0xFF));
    return this;
}

public ByteVector putInt(final int intValue) {
	if (intValue < 0) {
		throw new IllegalArgumentException("Negative integers are not supported");
	}

	int numBytes = 1;
	while (intValue > (255 * numBytes)) {
		numBytes++;
	}

	for (int i = numBytes - 1; i >= 0; i--) {
		byte currentByte = (byte) (intValue >>> (8 * i));
		put(currentByte);
	}

	return this;
}

public ByteVector putInt(final int intValue){
    if(intValue < 0){
        throw new IllegalArgumentException("Int value cannot be negative");
    }
    byte[] bytes = new byte[4];
    for(int i = 0; i < 4; i++){
        bytes[i] = (byte)(intValue >> (i * 8));
    }
    this.buffer.write(bytes);
    return this;
}

public ByteVector putInt(final int intValue) {
    if (intValue < 0) {
        throw new IllegalArgumentException("intValue must be non-negative");
    }

    int bytesNeeded = (int) Math.ceil(Integer.SIZE / 8.0);
    int remainingBytes = intValue;
    while (remainingBytes > 0) {
        this.add(remainingBytes & 0xFF);
        remainingBytes >>>= 8;
    }

    return this;
}

