public void abbreviate(final int nameStart,final StringBuffer buf){
    // Check if the start index is valid
    if(nameStart < 0 || nameStart > buf.length())
        throw new IllegalArgumentException("Invalid start index for name abbreviation");

    int i = nameStart;
    while i < buf.length() && buf.charAt(i) != ' ' && buf.charAt(i) != ',' && buf.charAt(i) != '.'{
        // Check if the current character is a letter
        if(Character.isLetter(buf.charAt(i)))
            buf.append(buf.charAt(i));
        i++;
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("No buffer provided");
    }
    if (nameStart > buf.length()) {
        throw new IllegalArgumentException("Start index cannot be greater than buffer length");
    }

    int i = nameStart;
    while (i < buf.length() && Character.isWhitespace(buf.charAt(i))) {
        i++;
    }

    String firstWord = null;
    while (i < buf.length() && !Character.isWhitespace(buf.charAt(i))) {
        firstWord = buf.substring(i, i + 1);
        break;
    }

    String restOfName = null;
    while (i < buf.length() && Character.isWhitespace(buf.charAt(i))) {
        restOfName = buf.substring(i + 1);
        break;
    }

    if (firstWord != null) {
        buf.setCharAt(i, firstWord.charAt(0));
    }
    if (restOfName != null) {
        buf.append(restOfName);
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    // Check if the input buffer is null
    if(buf == null){
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    // Check if the input nameStart is valid
    if(nameStart < 0 || nameStart >= buf.length()){
        throw new IllegalArgumentException("Invalid nameStart value");
    }
    // Abbreviate the name
    final int nameEnd = buf.length();
    for(int i = nameStart; i < nameEnd; i++){
        final char c = buf.charAt(i);
        if(c == ' ' || c == '-' || c == '.' || c == '_'){
            buf.setCharAt(i, '');
        }
    }
}

public void abbreviate(int nameStart, StringBuffer buf) {
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid nameStart index: " + nameStart);
    }
    if (buf == null) {
        throw new NullPointerException("buffer cannot be null");
    }

    String name = buf.substring(nameStart).trim();

    if (name.isEmpty()) {
        return;
    }

    String[] nameParts = name.split(" ");
    StringBuilder abbreviation = new StringBuilder();

    for (String part : nameParts) {
        if (!part.isEmpty()) {
            abbreviation.append(part.charAt(0));
        }
    }

    buf.replace(nameStart, nameStart + name.length(), abbreviation.toString());
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Calculate the length of the name
    int nameLength = buf.length() - nameStart;
    // If the name is too long, truncate it
    if (nameLength > 3) {
        buf.setLength(nameStart + 3);
    }
    // Abbreviate the name
    for (int i = nameStart; i < buf.length(); i++) {
        char c = buf.charAt(i);
        if (c == ' ') {
            buf.setCharAt(i, '.');
        }
    }
}

