private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true;
    }
    Set<V> neighbors = new HashSet<>(vertices);
    for (V vertex : vertices) {
        neighbors.addAll(graph.getNeighbors(vertex));
    }
    return vertices.equals(neighbors);
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the graph is null or empty
    if (graph == null || graph.isEmpty()) {
        return false;
    }
    // Check if the vertices set is null or empty
    if (vertices == null || vertices.isEmpty()) {
        return false;
    }
    // Check if the vertices set contains all the vertices of the graph
    if (!graph.containsAll(vertices)) {
        return false;
    }
    // Check if every vertex is connected to every other vertex
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.isEmpty()) {
        return false;
    }
    List<V> vertexList = new ArrayList<>(vertices);
    for (int i = 0; i < vertexList.size(); i++) {
        for (int j = i + 1; j < vertexList.size(); j++) {
            if (!graph.containsEdge(vertexList.get(i), vertexList.get(j))) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true;
    }
    V vertex = vertices.iterator().next();
    for (V v : graph.getNeighbors(vertex)) {
        if (!vertices.contains(v)) {
            return false;
        }
    }
    vertices.remove(vertex);
    return isClique(graph, vertices);
}

public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    for (V vertex : vertices) {
        for (V neighbor : graph.getNeighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<Integer> keys){
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Keys must not be null or empty!");
    }

    List<Integer> lowerBounds = new ArrayList<Integer>(keys.size());

    int minKey = Collections.min(keys);
    int maxKey = Collections.max(keys);

    for (Integer key : keys) {
        int lowerBound = minKey;
        if (key > lowerBound) {
            lowerBound = key;
        }
        lowerBounds.add(lowerBound);
    }

    for (int i = 0; i < keys.size() - 1; i++) {
        if (lowerBounds.get(i) > lowerBounds.get(i + 1)) {
            lowerBounds.set(i + 1, lowerBounds.get(i));
        }
    }

    return lowerBounds;
}

