public List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<Integer>();
    // Sort the keys in ascending order
    Collections.sort(keys);
    // Initialize the lower bound for the first key as 0
    lowerBounds.add(0);
    for (int i = 1; i < keys.size(); i++){
        // Find the largest element in the previous keys that is <= the current key
        int lowerBound = Collections.binarySearch(keys.subList(0, i), keys.get(i));
        if (lowerBound < 0){
            lowerBound = -lowerBound - 1;
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        int lowerBound = key.length();
        for (K otherKey : keys) {
            if (otherKey.equals(key)) {
                continue;
            }
            if (otherKey.startsWith(key)) {
                lowerBound = Math.min(lowerBound, otherKey.length());
            }
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

