        if (c == 'L' || c == '[' || c == 'I' || c == 'J' || c == 'F' || c == 'D') {
            numTypesToPop++;
        }
    }

    // Pop the types from the output frame stack
    for (int i = 0; i < numTypesToPop; i++) {
