public void pop(final String descriptor) {
    if (descriptor.isEmpty()) {
        throw new IllegalArgumentException("Invalid descriptor");
    }

    int numAbstractTypes = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        char c = descriptor.charAt(i);
        if (c == 'L') {
            numAbstractTypes++;
        } else if (c == '[') {
            numAbstractTypes++;
        } else if (c == ';') {
            break;
        }
    }

    if (numAbstractTypes == 0) {
        throw new IllegalArgumentException("Invalid descriptor");
    }

    for (int i = 0; i < numAbstractTypes; i++) {
        Object abstractType = getOutputFrameStack().pop();
        if (abstractType == null) {
            throw new IllegalArgumentException("Null value in output frame stack");
        }
    }
