        for(K otherKey : keys){
            if(!otherKey.equals(key) && upperBound == null){
                upperBound = key.compareTo(otherKey);
            }else if(upperBound != null && upperBound.compareTo(key.compareTo(otherKey)) == -1){
                upperBound = key.compareTo(otherKey);
            }
        }
        if(upperBound == null){
