    // check if keys is empty
    if(keys.isEmpty()){
        throw new IllegalArgumentException("Keys list is empty.");
    }
    // initialize the lower bounds list
    List<Integer> lowerBounds = new ArrayList<Integer>();
    // loop through each key
    for(K key : keys){
        // find the minimum lower bound for the current key
        int minLowerBound = Integer.MAX_VALUE;
        for(K otherKey : keys){
            if(key.compareTo(otherKey) < 0 && otherKey.compareTo(minLowerBound) < 0){
                minLowerBound = otherKey;
            }
        }
        // add the minimum lower bound to the list
        lowerBounds.add(minLowerBound);
    }
    return lowerBounds;
}

