public static String encodeTemplateNames(String s) {
    Charset asciiCharset = Charset.forName("US-ASCII");
    CharsetEncoder asciiEncoder = asciiCharset.newEncoder();
    CharsetDecoder asciiDecoder = asciiCharset.newDecoder();

    String encodedString = "";

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{' || c == '}') {
            byte[] encodedBytes = asciiEncoder.encode(Character.toString(c)).array();
            CharBuffer decodedChars = asciiDecoder.decode(ByteBuffer.wrap(encodedBytes));

            encodedString += "%" + Integer.toHexString(encodedBytes[0] & 0xFF).toUpperCase();
        } else {
            encodedString += c;
        }
    }

    return encodedString;
}

