    // Check if the relative path is valid
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid relative path: " + relativePath);
    }

    // Check if the path is valid
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Invalid path: " + path);
    }

    // Split the path into segments
    String[] pathSegments = path.split("/");

    // Split the relative path into segments
    String[] relativePathSegments = relativePath.split("/");

    // Check if the relative path is absolute
    if (relativePathSegments[0].isEmpty()) {
        // If the relative path is absolute, return the root path
        return "/";
    }

    // Check if the path and relative path have the same number of segments
    if (pathSegments.length != relativePathSegments.length) {
        // If the path and relative path have different numbers of segments,
        // throw an exception
        throw new IllegalArgumentException(
            "The path and relative path must have the same number of segments");
    }

    // Build the full path by concatenating the path segments with the relative path segments
    StringBuilder fullPath = new StringBuilder();
    for (int i = 0; i < pathSegments.length; i++) {
        fullPath.append(pathSegments[i]);
        if (i < relativePathSegments.length) {
            fullPath.append("/");
            fullPath.append(relativePathSegments[i]);
        }
    }

    // Return the full path
    return fullPath.toString();
}

