  // Find the index of the last dot
  int lastDotIndex = filename.lastIndexOf(".");

  // Check if there is a directory separator after the last dot
  if (lastDotIndex != -1) {
    // Find the index of the last directory separator
    int lastSeparatorIndex = indexOfLastSeparator(filename);

    // Check if there is a directory separator after the last dot
    if (lastSeparatorIndex > lastDotIndex) {
