    }
  }

  return lastDotIndex;
}

public static int indexOfLastSeparator(String filename) {
  // Check if the filename is null
  if (filename == null) {
    return -1;
  }

  // Find the index of the last directory separator using the normalizePath method
  int lastSeparatorIndex = normalizePath(filename).lastIndexOf("/");

  // If the index is -1, check if the filename is in Windows format and return the index of the last backslash
  if (lastSeparatorIndex == -1) {
    lastSeparatorIndex = filename.lastIndexOf("\\");
  }

  return lastSeparatorIndex;
}

public static String normalizePath(String filename) {
  // Check if the filename is null
  if (filename == null) {
    return null;
  }

  // Remove all leading and trailing forward slashes
  filename = filename.trim().replaceAll("^/+", "").replaceAll("/+$", "");

  // Remove all unnecessary characters and replace all backslashes with forward slashes
  filename = filename.replaceAll("[\\\\/]+", "/");

  return filename;
}

