public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnշSt> timeRanges) throws IOException {
    ObjectMapper mapper = new ObjectMapper();
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    JsonNode rootNode = mapper.readTree(file);
    for (ProfileAnschutzTimeRange timeRange : timeRanges) {
        long startTimestamp = timeRange.getStartTimestamp();
        long endTimestamp = timeRange.getEndTimestamp();
        for (JsonNode threadNode : rootNode.get("threads")) {
            int threadId = threadNode.get("id").asInt();
            JsonNode stackNode = threadNode.get("frames");
            List<FrameStack> frameStacks = new ArrayList<>();
            for (JsonNode frameNode : stackNode) {
                String frameName = frameNode.get("name").asText();
                boolean isNative = frameNode.get("isNative").asBoolean();
                boolean isJitCompiled = frameNode.get("isJitCompiled").asBoolean();
                FrameStack frameStack = new FrameStack(frameName, isNative, isJitCompiled);
                frameStacks.add(frameStack);
            }
            List<ThreadStack> threadStacks = new ArrayList<>();
            for (JsonNode threadStackNode : threadNode.get("stacks")) {
                int stackId = threadStackNode.get("id").asInt();
                String stackFile = threadStackNode.get("file").asText();
                String stackName = threadStackNode.get("name").asText();
                ThreadStack threadStack = new ThreadStack(stackId, stackFile, stackName);
                threadStacks.add(threadStack);
            }
            long timestamp = threadNode.get("timestamp").asLong();
            if (timestamp < startTimestamp || timestamp > endTimestamp) {
                continue;
            }
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, frameStacks, threadStacks, timestamp);
            threadSnapshots.add(threadSnapshot);
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid input");
    }

    List<String> lines = Files.lines(file.toPath()).collect(Collectors.toList());
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    for (String line : lines) {
        String[] tokens = line.split(",");
        if (tokens.length != 4) {
            continue; // invalid line
        }

        long threadId = Long.parseLong(tokens[0]);
        String threadName = tokens[1];
        Instant time = Instant.parse(tokens[2]);
        String state = tokens[3];

        ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, threadName, time, state);

        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeRange.contains(time)) {
                threadSnapshots.add(threadSnapshot);
                break;
            }
        }
    }

    return threadSnapshots;
}
